    <template v-if="activeTab==='editor'"><div v-if="!version" class="v21-empty">没有可编辑的版本。</div><template v-else><div class="v21-note">{{version.status==='draft'?`草稿 v${version.version}`:`v${version.version} 已发布。修改规则会创建新草稿。`}} · 支持单页 HTML、JSON 对象数组、列表到详情和分页列表。</div><div v-if="definition && !supportedDefinition" class="v21-error">此版本使用的节点超出 A06 工作台能力，请通过旧版界面查看；当前工作台只编辑通用记录的单页、JSON 或列表模板。</div><div v-if="definition && supportedDefinition" class="editor-grid"><div class="editor-form"><div class="v21-field"><label for="entry-url">入口 URL</label><input id="entry-url" v-model="definition.trigger.url" :disabled="version.status!=='draft'" placeholder="https://example.com/page" /></div><div class="v21-field"><label for="fetch-mode">获取方式</label><select id="fetch-mode" v-model="definition.trigger.fetch.mode" :disabled="version.status!=='draft'"><option value="http">Go HTTP</option><option value="browser">浏览器渲染</option></select></div><div v-if="definition.listing" class="v21-note">列表页发现详情，详情页写入记录；仅抓取入口同主机的链接。</div><div v-if="definition.listing" class="v21-field"><label>详情链接 CSS</label><input v-model="definition.listing.detail_selector" :disabled="version.status!=='draft'" placeholder="a.article-link[href]" /></div><div v-if="definition.listing" class="v21-field"><label>下一页 CSS</label><input v-model="definition.listing.next_selector" :disabled="version.status!=='draft'" placeholder="a[rel=next]，单页列表留空" /></div><div v-if="definition.listing" class="form-pair"><div class="v21-field"><label>最多列表页</label><input v-model.number="definition.listing.max_pages" type="number" min="1" max="100" :disabled="version.status!=='draft'" /></div><div class="v21-field"><label>连续空页停止</label><input v-model.number="definition.listing.max_empty_pages" type="number" min="1" max="10" :disabled="version.status!=='draft'" /></div></div><div v-if="isJSON" class="v21-field"><label for="items-path">数组路径</label><input id="items-path" v-model="definition.nodes[0].config.items_path" :disabled="version.status!=='draft'" placeholder="$.items" /></div><details v-if="definition.budget" class="v21-note"><summary>运行预算</summary><div class="form-pair"><div v-for="item in budgetFields" :key="item.key" class="v21-field"><label>{{item.label}}</label><input v-model.number="definition.budget[item.key]" type="number" min="1" :disabled="version.status!=='draft'" /></div></div><div class="v21-field"><label>允许域名（每行一个主机名）</label><textarea :value="definition.budget.allowed_domains.join('\n')" :disabled="version.status!=='draft'" @input="setAllowedDomains" /></div><small>按持久化任务和页面计数；重试不重置额度。域名必须包含入口主机。</small></details><h3>字段映射</h3><div v-for="(field,index) in fieldRules" :key="index" class="rule-row"><label :for="`selector-${index}`">{{field.name}} <span v-if="field.required">* 必填</span></label><input :id="`selector-${index}`" v-model="field.selector" :disabled="version.status!=='draft'" :placeholder="isJSON?'$.field':'CSS 选择器'" /><input v-if="!isJSON" v-model="field.attribute" :disabled="version.status!=='draft'" :aria-label="`${field.name} 属性`" placeholder="属性，可留空" /></div><div class="v21-actions"><el-button v-if="version.status==='draft'" :loading="busy" @click="saveDraft">保存规则为新草稿</el-button><el-button v-else @click="createDraft">创建编辑草稿</el-button><el-button @click="showJSON=!showJSON">{{showJSON?'隐藏':'高级'}} JSON 定义</el-button></div><div v-if="showJSON" class="v21-field json-editor"><label for="definition-json">工作流定义 JSON</label><textarea id="definition-json" v-model="definitionText" :disabled="version.status!=='draft'" @focus="jsonFocused=true" @blur="parseJSONEditor" /><small class="v21-muted">高级编辑与字段表单对应同一份定义；失焦时校验并同步。</small></div></div><div class="editor-preview"><h3>样例与预览</h3><p class="v21-muted">先保存草稿，再用样例验证。预览不会写正式记录或触发插件。</p><div class="v21-field"><label for="sample-source">样例来源</label><select id="sample-source" v-model="sampleSource" :disabled="version.status!=='draft'"><option value="live">实时获取</option><option value="paste">粘贴原文</option><option value="document">历史文档</option></select></div><div v-if="definition.listing" class="v21-field"><label>页面角色</label><select v-model="sampleRole" :disabled="version.status!=='draft'"><option value="list">列表页</option><option value="detail">详情页</option></select></div><div v-if="definition.listing && sampleRole==='detail'" class="v21-field"><label>详情页 URL</label><input v-model="samplePageURL" :disabled="version.status!=='draft'" placeholder="https://example.com/detail/1" /></div><div v-if="sampleSource==='paste'" class="v21-field"><label for="sample-content">{{isJSON?'JSON':'HTML'}} 原文</label><textarea id="sample-content" v-model="sampleContent" :disabled="version.status!=='draft'" placeholder="粘贴页面原文" /></div><div v-if="sampleSource==='document'" class="v21-field"><label for="document-id">历史文档 ID</label><input id="document-id" v-model.number="documentId" type="number" min="1" :disabled="version.status!=='draft'" /></div><div class="v21-field"><label for="sample-outcome">预期结果</label><select id="sample-outcome" v-model="sampleOutcome" :disabled="version.status!=='draft'"><option value="success">正常提取</option><option value="error">预期字段或校验错误</option><option v-if="definition.listing && sampleRole==='list'" value="empty_list">空列表且无下一页</option></select></div><div v-if="sampleOutcome==='error'" class="v21-field"><label for="sample-expected-error">错误包含文字</label><input id="sample-expected-error" v-model="sampleExpectedError" :disabled="version.status!=='draft'" placeholder="例如 required field" /></div><div class="v21-actions"><el-button :disabled="version.status!=='draft'" :loading="busy" @click="saveSample">保存样例</el-button><el-button :disabled="!samples.length" :loading="busy" @click="checkSamples">回归全部样例</el-button></div><div v-if="!samples.length" class="v21-empty">当前版本还没有样例。保存至少一个样例后才能发布。</div><div v-for="sample in samples" :key="sample.id" class="v21-row"><div><strong>{{sample.note||`${sample.source} 样例 #${sample.id}`}}</strong><small>{{sample.page_role}} · {{sample.expected_outcome==='error'?'预期报错':sample.expected_outcome==='empty_list'?'预期空列表':'正常提取'}} · {{sample.content_type}} · {{sample.page_url}}</small></div><div class="v21-actions"><el-button text @click="previewSample(sample.id)">预览</el-button><el-button v-if="version.status==='draft'" text type="danger" @click="deleteSample(sample.id)">删除</el-button></div></div></div></div></template></template>
    <template v-if="activeTab==='preview'"><div class="preview-head"><div><h3>完整 dry-run</h3><p class="v21-muted">{{preview?.fetched_live?'本次访问网络':'使用保存的样例快照，未访问网络'}} · 不写正式数据</p></div><el-button :disabled="!samples.length||busy" :loading="busy" @click="checkSamples">回归样例</el-button></div><p v-if="checkError" class="v21-error" role="alert">{{checkError}}</p><section v-if="checks.length" class="sample-checks"><h3>样例回归 · {{checks.filter(item=>item.passed).length}} / {{checks.length}} 通过</h3><button v-for="item in checks" :key="item.sample_id" class="check-item" :class="{active:preview===item}" @click="preview=item"><span><strong>{{samples.find(sample=>sample.id===item.sample_id)?.note||`样例 #${item.sample_id}`}}</strong><small>{{item.error||'查看字段与保存决策'}}</small></span><span class="v21-status" :class="item.passed?'ok':'bad'">{{item.passed?'通过':'失败'}}</span></button></section><div v-if="!preview" class="v21-empty">在“配置与样例”中选择样例预览，查看每一步和预计保存决策。</div><template v-else><h3 v-if="preview.sample_id">样例 #{{preview.sample_id}} · {{preview.passed?'通过':'失败'}}</h3><p class="v21-note">预期：{{preview.expected_outcome}} · 实际：{{preview.actual_outcome}}</p><p v-if="preview.actual_error" class="v21-note">实际错误：{{preview.actual_error}}</p><p v-if="preview.error" class="v21-error">{{preview.error}}</p><div v-for="(step,index) in preview.steps" :key="index" class="step-card"><div><span class="v21-status">{{step.type}}</span><strong>{{step.node}}</strong><small>候选 {{step.candidate+1}}</small></div><dl><template v-for="(value,key) in step.values" :key="key"><dt>{{key}}</dt><dd>{{display(value)}}</dd></template></dl></div><div v-if="preview.page_role==='list'" class="v21-note">发现详情 {{preview.discovered_urls?.length||0}} 条；下一页：{{preview.next_url||'无'}}。列表样例不会写入记录，请另存详情样例。</div><h3 v-else>预计保存决策</h3><div v-for="decision in preview.decisions" :key="decision.index" class="v21-row"><div><strong>{{decision.canonical_key||`候选 ${decision.index+1}`}}</strong><small>{{decision.reason||display(decision.values||{})}}</small></div><span class="v21-status" :class="decision.decision==='invalid'||decision.decision==='conflict'?'bad':decision.decision==='created'?'ok':'warn'">{{decision.decision}}</span></div></template></template>
    <template v-if="activeTab==='versions'"><h3>版本历史</h3><div v-for="item in versions" :key="item.id" class="v21-row"><div><strong>v{{item.version}} · {{item.status}}</strong><small>{{formatDate(item.created_at)}} · 版本 #{{item.id}}</small></div><el-button text @click="openVersion(item)">查看</el-button></div></template>
    <template v-if="activeTab==='schedule'"><h3>定时与 API 触发</h3><p class="v21-note">定时配置持久保存，服务重启后自动恢复。API 触发需登录令牌，当前只接受采集器 ID，不允许覆盖运行参数或凭据。</p><div class="editor-grid"><div class="editor-form"><div class="v21-field"><label>启用定时</label><el-switch v-model="scheduleForm.enabled" :disabled="!selectedWorkflow.published_version_id" /></div><div class="v21-field"><label>Cron（五段，分 时 日 月 周）</label><input v-model="scheduleForm.cron" placeholder="0 9 * * *" /></div><div class="v21-field"><label>时区</label><input v-model="scheduleForm.timezone" placeholder="Asia/Shanghai" /></div><div class="v21-field"><label>并发策略</label><select v-model="scheduleForm.concurrency_policy"><option value="skip">跳过：已有运行时记跳过</option><option value="queue">排队：等已有运行结束</option></select></div><el-button type="primary" :loading="busy" @click="saveSchedule">保存定时配置</el-button></div><div class="editor-preview"><h3>调度状态</h3><p>下一次：{{formatDate(schedule?.next_run_at)}}</p><p>上一次：{{formatDate(schedule?.last_run_at)}}</p><p>API：POST /api/v2/workflows/run/api</p><pre class="json-box">{"workflow_id": {{selectedWorkflow.id}}}</pre><h3>最近触发</h3><div v-if="!scheduleEvents.length" class="v21-empty">暂无定时触发。</div><div v-for="event in scheduleEvents" :key="event.id" class="v21-row"><span>{{formatDate(event.scheduled_at)}} · {{event.status}} {{event.reason}}</span><router-link v-if="event.run_id" class="v21-link" :to="{path:'/workspace/runs',query:{id:String(event.run_id)}}">运行 #{{event.run_id}}</router-link></div></div></div></template>
    <template v-if="activeTab==='runs'"><h3>最近运行</h3><div v-if="!collectorRuns.length" class="v21-empty">此采集器尚未正式运行。</div><div v-for="run in collectorRuns" :key="run.id" class="v21-row"><div><strong>{{run.status}} · 运行 #{{run.id}}</strong><small>{{formatDate(run.created_at)}} · {{triggerName(run.trigger_type)}} · 版本 #{{run.workflow_version_id}}</small></div><router-link class="v21-link" :to="{path:'/workspace/runs',query:{id:String(run.id)}}">查看任务 →</router-link></div></template>
   </template></section></div>
  <el-dialog v-model="wizardOpen" title="添加来源" width="min(850px,96vw)" :close-on-click-modal="false"><div class="wizard-steps"><span v-for="(label,index) in wizardLabels" :key="label" :class="{active:index===wizardStep}">{{index+1}} {{label}}</span></div><div v-if="wizardStep===0"><p>选择目标数据集。同类记录将按唯一键合并，保留各自来源。</p><div class="v21-field"><label for="wizard-dataset">目标数据集</label><select id="wizard-dataset" v-model.number="wizard.datasetId"><option v-for="dataset in datasets" :key="dataset.id" :value="dataset.id">{{dataset.name}}</option></select></div></div><div v-if="wizardStep===1"><div class="v21-field"><label for="wizard-name">采集器名称</label><input id="wizard-name" v-model="wizard.name" placeholder="例如：站点文章详情" /></div><div class="v21-field"><label for="wizard-url">目标 URL</label><input id="wizard-url" v-model="wizard.url" placeholder="https://example.com/page" /></div><div class="v21-field"><label for="wizard-template">页面类型</label><select id="wizard-template" v-model="wizard.templateCode"><option v-for="template in templates" :key="template.code" :value="template.code">{{template.name}} · {{template.description}}</option></select></div><p class="v21-note">列表模板先预览列表链接，创建后还需保存一份详情页样例才能发布。</p></div><div v-if="wizardStep===2"><div class="v21-field"><label for="wizard-sample-source">样例来源</label><select id="wizard-sample-source" v-model="wizardSampleSource"><option value="live">实时获取目标 URL</option><option value="paste">粘贴原文</option></select></div><div v-if="wizardSampleSource==='paste'" class="v21-field"><label for="wizard-sample-content">页面或 JSON 原文</label><textarea id="wizard-sample-content" v-model="wizardSampleContent" placeholder="粘贴完整 HTML 或 JSON" /></div><p class="v21-note">样例会绑定草稿版本；预览不会写入正式记录。</p></div><div v-if="wizardStep===3"><p>按数据集字段设置 {{wizard.templateCode==='json_api'?'JSONPath':'CSS'}} 提取规则。必填字段和唯一键必须能提取。</p><div v-if="wizardRule?.listing" class="v21-field"><label>详情链接 CSS</label><input v-model="wizardRule.listing.detail_selector" placeholder="a.article-link[href]" /></div><div v-if="wizardRule?.listing" class="v21-field"><label>下一页 CSS</label><input v-model="wizardRule.listing.next_selector" placeholder="单页列表留空" /></div><div v-if="wizardRule?.listing" class="form-pair"><div class="v21-field"><label>最多列表页</label><input v-model.number="wizardRule.listing.max_pages" type="number" min="1" max="100" /></div><div class="v21-field"><label>连续空页停止</label><input v-model.number="wizardRule.listing.max_empty_pages" type="number" min="1" max="10" /></div></div><div v-if="wizard.templateCode==='json_api'&&wizardRule" class="v21-field"><label for="wizard-items-path">JSON 对象数组路径</label><input id="wizard-items-path" v-model="wizardRule.nodes[0].config.items_path" placeholder="$.items 或 $" /></div><div v-for="(field,index) in wizardFields" :key="index" class="v21-field"><label :for="`wizard-field-${index}`">{{field.name}}{{field.required?' · 必填':''}}{{field.multiple?' · 多值':''}}</label><input :id="`wizard-field-${index}`" v-model="field.selector" :placeholder="wizard.templateCode==='json_api'?'$.field':'CSS 选择器'" /><input v-if="wizard.templateCode!=='json_api'" v-model="field.attribute" :aria-label="`${field.name} 提取属性`" placeholder="属性，例如 href；留空提取文本" /></div></div><div v-if="wizardStep===4"><p>将创建草稿、保存样例并运行完整预览。请在预览结果中核对每一步及预计保存动作，再发布版本。</p><div class="v21-note">目标：{{wizard.url}}<br>数据集：{{datasetName(wizard.datasetId)}}<br>字段数：{{wizardFields.length}}<br>样例：{{wizardSampleSource==='live'?'实时获取':'粘贴原文'}}</div></div><template #footer><el-button @click="wizardOpen=false">取消</el-button><el-button v-if="wizardStep>0" @click="wizardStep--">上一步</el-button><el-button v-if="wizardStep<4" type="primary" @click="wizardNext">下一步</el-button><el-button v-else type="primary" :loading="busy" @click="createWorkflow">创建并预览</el-button></template></el-dialog>
 </div>
</template>
<script setup lang="ts">
import { computed,onMounted,reactive,ref,watch } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import { ElMessage,ElMessageBox } from 'element-plus';
import { api,errorText,workflowPages,type Dataset,type Definition,type Preview,type Run,type Sample,type SampleOutcome,type Schedule,type ScheduleEvent,type Template,type Version,type Workflow } from './api';
import { projectId } from './state';
import { datasetDefinition,editableDefinition } from './rules';
const route=useRoute(),router=useRouter();const allDatasets=ref<Dataset[]>([]),allWorkflows=ref<Workflow[]>([]),templates=ref<Template[]>([]),versions=ref<Version[]>([]),samples=ref<Sample[]>([]),collectorRuns=ref<Run[]>([]),selectedId=ref(0),version=ref<Version|null>(null),definition=ref<Definition|null>(null),preview=ref<Preview|null>(null),activeTab=ref('editor'),loading=ref(false),busy=ref(false),error=ref(''),showJSON=ref(false),definitionText=ref(''),savedDefinition=ref('');
const checks=ref<Preview[]>([]),checkError=ref('');
const schedule=ref<Schedule|null>(null),scheduleEvents=ref<ScheduleEvent[]>([]),scheduleForm=reactive({cron:'0 9 * * *',timezone:'Asia/Shanghai',enabled:false,concurrency_policy:'skip' as 'skip'|'queue'});
const sampleSource=ref('live'),sampleRole=ref('trigger'),samplePageURL=ref(''),sampleContent=ref(''),documentId=ref<number|undefined>(),sampleOutcome=ref<SampleOutcome>('success'),sampleExpectedError=ref(''),wizardOpen=ref(false),wizardStep=ref(0),wizardLabels=['目标数据','来源与模板','获取样例','定义输出','预览与发布'],wizardSampleSource=ref('live'),wizardSampleContent=ref(''),wizardRule=ref<Definition|null>(null),jsonFocused=ref(false);
const wizard=reactive({datasetId:0,name:'',url:'',templateCode:'single_page'});
const repairTask=computed(()=>Number(route.query.repair_task)||0);
function applyRepairContext(){if(!repairTask.value||Number(route.query.id)!==selectedId.value||!definition.value)return;const document=Number(route.query.repair_document)||0;sampleSource.value=document?'document':'live';documentId.value=document||undefined;const role=String(route.query.repair_role||'trigger');sampleRole.value=definition.value.listing&&(role==='list'||role==='detail')?role:'trigger';const url=String(route.query.repair_url||'');if(/^https?:\/\//.test(url))samplePageURL.value=url;activeTab.value='editor';}
const datasets=computed(()=>allDatasets.value.filter(d=>d.project_id===projectId.value));const workflows=computed(()=>allWorkflows.value.filter(w=>w.project_id===projectId.value));const selectedWorkflow=computed(()=>workflows.value.find(w=>w.id===selectedId.value));const fieldRules=computed<any[]>(()=>definition.value?.nodes.find(n=>n.type==='extract')?.config.fields||[]);const isJSON=computed(()=>definition.value?.nodes[0]?.config.content_type==='json');const wizardFields=computed<any[]>(()=>wizardRule.value?.nodes[0]?.config.fields||[]);const tabs=[{id:'editor',name:'配置与样例'},{id:'preview',name:'预览结果'},{id:'schedule',name:'触发器'},{id:'runs',name:'运行'},{id:'versions',name:'版本'}];
